-- Modern Player Motion: loader. Plan and change log: addons/MPMDIDDY/PLAN.md
MPM = MPM or {}

local shared = { "mpm/sh_config.lua", "mpm/sh_state.lua", "mpm/sh_input.lua", "mpm/sh_move.lua", "mpm/sh_mantle.lua" }
local client = { "mpm/cl_debug.lua", "mpm/cl_ground.lua", "mpm/cl_gun.lua", "mpm/cl_menu.lua" }

-- generated by mpm_build.py (clip speeds / foot plants); optional until anims are built
local parts = file.Find("mpm/data/clips_p*.lua", "LUA") or {}
table.sort(parts)
if #parts == 0 and file.Exists("mpm/data/clips.lua", "LUA") then parts = { "clips.lua" } end
if #parts > 0 then
    for _, f in ipairs(parts) do table.insert(shared, "mpm/data/" .. f) end
    table.insert(shared, "mpm/sh_anim.lua")
    table.insert(shared, "mpm/sh_anim_trans.lua")
    table.insert(shared, "mpm/sh_anim_guns.lua")
    table.insert(shared, "mpm/sh_flinch.lua")
end
table.insert(shared, "mpm/sh_animtest.lua")

for _, f in ipairs(shared) do
    if SERVER then AddCSLuaFile(f) end
    include(f)
end

for _, f in ipairs(client) do
    if SERVER then AddCSLuaFile(f) else include(f) end
end
